// Helper function to calculate VAG code from P-code
// Verified against known VCDS pairings: the VAG 5-digit code offset grows by
// 24 per P-code "thousand": P0xxx +16384, P1xxx +16408, P2xxx +16432,
// P3xxx +16456 (e.g. 16485/P0101, 17965/P1557, 18434/P2002, 19557/P3101)
function pCodeToVag(pCode: string): number {
  const pNum = parseInt(pCode.substring(1), 10);
  return 16384 + pNum + 24 * Math.floor(pNum / 1000);
}

