// Helper to get description from mixed format definitions
function getDescription(info: DTCDefinition): string {
  // Prefer descriptionFR for French, fallback to description
  return info.descriptionFR || info.description || '';
}

// Helper to get system from mixed format definitions
function getSystem(info: DTCDefinition): string {
  // If systemKey is used, convert to French system name
  if (info.systemKey) {
    return DTC_SYSTEMS[info.systemKey as keyof typeof DTC_SYSTEMS] || info.systemKey;
  }
  return info.system || '';
}

// Helper to get system key from mixed format definitions
function getSystemKeyFromInfo(info: DTCDefinition): string {
  if (info.systemKey) return info.systemKey;
  // Try to find the key from French system name
  const systemName = info.system || '';
  for (const [key, value] of Object.entries(DTC_SYSTEMS)) {
    if (value === systemName) return key;
  }
  return 'OTHER';
}

// Build the VAG code indexed database from P-code definitions
export const VAG_DTC_DATABASE: Record<number, DTCInfo> = {};

// Populate the VAG database
for (const [pCode, info] of Object.entries(DTC_DEFINITIONS)) {
  const vagCode = pCodeToVag(pCode);
  VAG_DTC_DATABASE[vagCode] = {
    code: pCode,
    description: getDescription(info),
    system: getSystem(info),
  };
}

// Marker text used by placeholder entries for codes with no publicly
// documented description (Bosch EDC16 internal / unidentified VAG codes).
const UNDOCUMENTED_MARKER = 'not publicly documented';

/**
 * Whether a DTC has a real, documented description.
 * Codes without one (placeholder entries or absent from the database)
 * must not be shown in DTC lists.
 * Self-maintaining: adding a real description to DTC_DEFINITIONS
 * automatically makes the code visible again.
 */
export function isDocumentedDTC(pCode: string): boolean {
  const info = DTC_DEFINITIONS[pCode];
  if (!info) return false;
  const en = info.descriptionEN || '';
  const frOrLegacy = info.descriptionFR || info.description || '';
  if (!en && !frOrLegacy) return false;
  return !en.includes(UNDOCUMENTED_MARKER);
}

/**
 * Get DTC info by P-code (returns French description by default)
 */
export function getDTCInfoByPCode(pCode: string): DTCInfo | null {
  const info = DTC_DEFINITIONS[pCode];
  if (!info) return null;
  return {
    code: pCode,
    description: getDescription(info),
    system: getSystem(info),
  };
}

/**
 * Get DTC info by VAG code (returns French description by default)
 */
export function getDTCInfoByVagCode(vagCode: number): DTCInfo | null {
  return VAG_DTC_DATABASE[vagCode] || null;
}

/**
 * Get bilingual DTC info by P-code
 */
export function getBilingualDTCInfoByPCode(pCode: string): BilingualDTCInfo | null {
  const info = DTC_DEFINITIONS[pCode];
  if (!info) return null;
  return {
    code: pCode,
    descriptionEN: info.descriptionEN || '',
    descriptionFR: info.descriptionFR || info.description || '',
    systemKey: getSystemKeyFromInfo(info),
  };
}

/**
 * Get system key for a DTC code
 */
export function getDTCSystemKey(pCode: string): string {
  const info = DTC_DEFINITIONS[pCode];
  if (!info) return 'OTHER';
  return getSystemKeyFromInfo(info);
}

/**
 * Convert P-code to VAG code
 */
export function convertPCodeToVag(pCode: string): number {
  return pCodeToVag(pCode);
}

/**
 * Convert VAG code to P-code
 */
export function convertVagToPCode(vagCode: number): string {
  // Inverse of pCodeToVag: find the "thousand" bucket t such that
  // pNum = vagCode - 16384 - 24*t falls within [1000*t, 1000*(t+1))
  for (let t = 0; t <= 9; t++) {
    const pNum = vagCode - 16384 - 24 * t;
    if (Math.floor(pNum / 1000) === t) {
      return `P${pNum.toString(10).padStart(4, '0')}`;
    }
  }
  // Fallback (should not happen for valid VAG codes)
  const pCodeNum = Math.max(0, vagCode - 16384);
  return `P${pCodeNum.toString(10).padStart(4, '0')}`;
}
